const upsertResidentSocietyMember = `-- name: UpsertResidentSocietyMember :one
INSERT INTO society_members (society_id, user_id, role, status, invited_by, metadata)
VALUES ($1, $2, 'resident', 'active', $3, '{}'::jsonb)
ON CONFLICT (society_id, user_id) DO UPDATE
SET
    role = CASE
        WHEN society_members.role IN ('owner', 'admin', 'staff') THEN society_members.role
        ELSE 'resident'
    END,
    status = 'active',
    removed_by = NULL,
    removed_at = NULL,
    remove_reason = NULL,
    updated_at = NOW()
RETURNING id, society_id, user_id, role, status, invited_by, joined_at, removed_by, removed_at, remove_reason, metadata, created_at, updated_at
`

